import sqlite3

from langchain.tools import tool

DB_PATH = "/var/data/accounts.db"


@tool
def delete_user_account(user_id: int, confirm_email: str) -> str:
    if not isinstance(user_id, int) or user_id <= 0:
        return "Error: user_id must be a positive integer"
    if not confirm_email or "@" not in confirm_email:
        return "Error: confirm_email must be a valid email address"

    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.cursor()
        cur.execute("SELECT email FROM users WHERE id = ?", (user_id,))
        row = cur.fetchone()
        if row is None:
            return f"Error: no user with id {user_id}"
        if row[0].strip().lower() != confirm_email.strip().lower():
            return "Error: confirmation email does not match the account"

        cur.execute("DELETE FROM api_keys WHERE user_id = ?", (user_id,))
        keys_removed = cur.rowcount
        cur.execute("DELETE FROM preferences WHERE user_id = ?", (user_id,))
        prefs_removed = cur.rowcount
        cur.execute("DELETE FROM users WHERE id = ?", (user_id,))
        conn.commit()
    except sqlite3.Error as exc:
        conn.rollback()
        return f"Error: database failure: {exc}"
    finally:
        conn.close()

    return (
        f"Deleted user {user_id}; removed {keys_removed} API keys "
        f"and {prefs_removed} preference rows"
    )

import re
import sqlite3
from datetime import datetime, timezone

DB_PATH = "/var/data/accounts.db"


def _build_updates(display_name, phone, locale):
    fields = {}
    if display_name is not None:
        fields["display_name"] = display_name.strip()[:80]
    if phone is not None:
        digits = re.sub(r"[^\d+]", "", phone)
        fields["phone"] = digits
    if locale is not None:
        fields["locale"] = locale.strip().replace("_", "-")
    return fields


def update_user_profile(user_id: int, display_name: str = None, phone: str = None, locale: str = None) -> dict:
    fields = _build_updates(display_name, phone, locale)
    if not fields:
        return {"updated": False, "reason": "no fields provided"}

    fields["updated_at"] = datetime.now(timezone.utc).isoformat()
    assignments = ", ".join(f"{col} = ?" for col in fields)
    values = list(fields.values()) + [user_id]

    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute(
            f"UPDATE users SET {assignments} WHERE id = ?", values
        )
        conn.commit()
        changed = cur.rowcount
    finally:
        conn.close()

    if changed == 0:
        return {"updated": False, "reason": "user not found"}
    return {"updated": True, "fields": [k for k in fields if k != "updated_at"]}
